                                  'Row],[TX_ID]],tblLoad[Phase_e],"1PH",tblLoad[PhaseAssign],"L1")+(SUMIFS(tblLoad[Run_kVA],tblLoad[TX],tblTX[[#This '
                                  'Row],[TX_ID]],tblLoad[Phase_e],"1PH",tblLoad[PhaseAssign],"L1-L2")+SUMIFS(tblLoad[Run_kVA],tblLoad[TX],tblTX[[#This '
